    "domain": "Standard English Conventions",
    "category": "Boundaries & Grammar",
    "p": "Artificial photosynthesis is a chemical process that replicates the natural process of photosynthesis <span class=\"sat-blank\"></span>. Scientists to perfect this technology. If successful, it could provide a clean, renewable source of energy. The process involves capturing sunlight and converting it into chemical energy. This energy is then stored for later use. The goal is to create a system that can efficiently convert sunlight into usable energy.",
