    "e": "The subject \"Scientists\" is a plural noun, which requires the plural verb \"are working\". Additionally, the surrounding text uses the present tense (\"is\", \"replicates\"), so the present continuous \"are working\" maintains the proper tense and subject-verb agreement. Choices A and D use singular verbs, and Choice B uses the past tense.",
