    "p": "The Wizard of Earthsea is a fantasy novel written by Ursula K <span class=\"sat-blank\"></span>. Le Guin. The story revolves around a young boy named Ged who discovers he has magical powers. for wizards where he learns to control his powers. However, in his arrogance, Ged releases a shadow creature into the world. The rest of the novel follows Ged's journey to defeat this creature and restore balance to the world.",
