    "module": "Module 1",
    "qnum_in_module": 24,
    "domain": "Expression of Ideas",
    "category": "Transitions",
    "p": "African cosmology has had a profound influence on star lore around the world <span class=\"sat-blank\"></span>. For instance, in many African societies, the Pleiades star cluster is associated with agricultural cycles, signifying the beginning or end of growing seasons. the constellation Orion was often viewed as a celestial representation of Osiris, the Egyptian god of the afterlife.",
