    "domain": "Craft and Structure",
    "category": "Words in Context",
    "p": "St <span class=\"sat-blank\"></span>. Peter, the foremost apostle of Jesus and the first Pope of the Catholic Church, holds a deeply impactful role in Christian history. His life and teachings continue to the Church's doctrines, shaping the spiritual journey of millions. St. Peter's influence, even after his death, remains unyielding, guiding the Church's approach to faith and worship. His steadfast commitment to spreading the teachings of Jesus and his unwavering faith in the face of adversity have cemented his status as a pivotal figure in the Church's narrative.",
    "q": "Which choice completes the text with the most logical and precise word or phrase?",
    "o": [
      "inform",
      "entertain",
      "distract",
      "amuse"
    ],
    "a": 0,
    "e": "In this context, \"inform\" means to give an underlying principle or essential quality to something, or to influence and shape it. The passage discusses how St. Peter's life and teachings have a \"deeply impactful role\" and \"shape the spiritual journey of millions,\" making \"inform\" the precise word to describe how his legacy fundamentally guides the Church's doctrines.",
