    "category": "Central Ideas and Details",
    "p": "Sales tax is a consumption tax imposed by the government on the sale of goods and services. It is typically calculated as a percentage of the purchase price and varies depending on the location of the sale. Some areas may have multiple layers of sales tax, such as state and local governments. Sales tax revenue is often used to fund public services and infrastructure projects, making it an essential source of income for governments.",
