    "qnum_in_module": 10,
    "domain": "Craft and Structure",
    "category": "Reading & Writing Comprehension",
    "p": "Mining Engineer, Maria Lopez and her team conducted an extensive study on the impact of coal mining on the surrounding environment. By analyzing the soil composition and water quality in regions where mining was prevalent, they discovered that areas closer to the mining sites had a higher concentration of heavy metals, leading to soil degradation. However, these regions showed an unexpected increase in certain plant species that are known to be tolerant to heavy metals. Lopez hypothesized that the mining activities, despite causing soil degradation, were indirectly promoting biodiversity by favoring these specific plant species.",
    "q": "Which observation, if true, would most directly challenge Lopez's hypothesis?",
    "o": [
      "In regions far from the mining sites, soil composition was found to contain minimal heavy metals, yet there was an increase in the same plant species.",
      "In regions not included in the study, mining activities led to a decrease in the overall biodiversity, including the heavy metal-tolerant species.",
      "In several areas not part of the study, there was a decrease in the specific plant species despite the presence of heavy metals in the soil.",
      "In some areas included in the study, mining activities resulted in an increase in different plant species, not known to be heavy metal tolerant."
    ],
    "a": 0,
    "e": "Choice A is correct because it severs the causal link proposed by Lopez. If the same heavy-metal-tolerant plant species increased in areas without heavy metals, then the increase in those species is likely due to another factor, directly challenging the hypothesis that mining-induced heavy metals promote their growth. The other choices fail to provide this specific disconfirming evidence.",
    "chart": null,
