    "domain": "Craft and Structure",
    "category": "Reading & Writing Comprehension",
    "p": "The Treaty of Paris, signed in 1898, ended the Spanish-American War and significantly affected Asia. Spain ceded control of the Philippines to the United States, marking the U.S.'s first major overseas colony. Despite resistance from Filipino nationalists, who had been fighting for independence from Spain, the U.S. established a colonial government. The Treaty also raised questions about America's role in Asia, especially regarding the balance of power with other colonial nations. Historians argue that the Treaty laid the groundwork for the U.S.'s future involvement in Asian affairs, particularly in the Pacific theater during World War II.",
    "q": "Which statement, if proven true, would most significantly support the argument that the Treaty of Paris had a profound impact on the U.S.'s future involvement in Asia?",
