    "category": "Boundaries & Grammar",
    "p": "Researchers investigating the principles of photosynthesis have determined why certain aquatic plants in the Northern Hemisphere grow towards the surface of the water <span class=\"sat-blank\"></span>. Contrasting with similar species in the Southern Hemisphere, which exhibit the opposite behavior due to in the Northern Hemisphere, sunlight penetrates the water from above, encouraging plants to grow upwards towards the light. Conversely, in the Southern Hemisphere, light diffraction patterns caused by the angle of the sun result in a different growth direction, away from the surface and towards deeper waters.",
