    "p": "In a recent study exploring the impact of workplace environment on productivity, researchers observed the lighting conditions in various offices <span class=\"sat-blank\"></span>. The brightness of the lights in the offices in some locations, they were extremely bright, while in others, they were kept at a more subdued level. The study found that lighting intensity had a significant effect on employee productivity and mood.",
