    "domain": "Standard English Conventions",
    "category": "Boundaries & Grammar",
    "p": "Existentialism, a philosophical movement that dominated 20th-century philosophy, emphasizes the existence of the individual as a free and responsible agent <span class=\"sat-blank\"></span>. This movement, which was primarily influenced by the works of Soren Kierkegaard and Friedrich Nietzsche, argues that individuals and must take personal responsibility for themselves. Existentialists believe that life is a series of choices, creating stress and anxiety but also offering freedom and opportunities.",
