    "variant": "Ninja Practice Test 1",
    "variant_num": 1,
    "module": "Module 2",
    "qnum_in_module": 23,
    "domain": "Expression of Ideas",
    "category": "Transitions",
    "p": "Autonomous vehicles are purported to bring about a significant change in the field of transportation, reducing the frequency of traffic accidents and increasing efficiency in fuel consumption <span class=\"sat-blank\"></span>. They are designed to perceive their surroundings and navigate without human input, using technologies like radar, lidar, GPS, and computer vision. these vehicles also have the potential to redefine urban spaces, as less space would be needed for parking lots, more lanes could be accommodated on the roads, and traffic could be better managed,",
