    "category": "Rhetorical Synthesis",
    "p": "• • • • While researching a topic, a student has taken the following notes: Ernest Hemingway was an American author and journalist. He won the Nobel Prize in Literature in 1954. Hemingway's style is known for its simplicity and directness. He often used an iceberg theory of writing, leaving much unsaid and beneath the surface. • The Old Man and the Sea is one of his most famous works.",
