    "domain": "Expression of Ideas",
    "category": "Rhetorical Synthesis",
    "p": "While researching a topic, a student has taken the following notes: • The Human Genome Project was an international research project that aimed to map the entire human genome. • It was a 13-year project coordinated by the US Department of Energy and the National Institutes of Health. • The project was completed in 2003, two years ahead of its original schedule. • The data from the project has been made freely available to researchers around the world. • The project has led to significant medical and scientific discoveries.",
    "q": "The student wants to describe the impact of the Human Genome Project. Which choice most effectively uses relevant information from the notes to accomplish this goal?",
