    "domain": "Expression of Ideas",
    "category": "Rhetorical Synthesis",
    "p": "While researching a topic, a student has taken the following notes: • Archimedes was a Greek mathematician, physicist, and inventor. Archimedes is known for his contributions to geometry, particularly the measurement of geometric shapes and volumes. • The Archimedes' Principle states that the buoyant force on an object submerged in a fluid is equal to the weight of the fluid displaced by the object. • Archimedes is also credited with inventing the Archimedes' Screw, a device used to raise water from a lower to a higher level.",
    "q": "Which choice most effectively uses relevant information from the notes to describe Archimedes' significant contribution to the field of physics?",
    "o": [
      "Archimedes' work in geometry, especially in measuring shapes and volumes, revolutionized the field of mathematics.",
      "Archimedes, primarily known for his mathematical genius, also made some contributions to physics with the Archimedes' Principle.",
      "Archimedes' major contribution to physics was the invention of the Archimedes' Screw, which is used for water irrigation.",
      "Archimedes' Principle, stating that the buoyant force on a submerged object equals the weight of the displaced fluid, is a cornerstone in physics."
    ],
    "a": 3,
    "e": "Choice D is correct because it selects the specific note relevant to physics (Archimedes' Principle) and accurately describes it as a significant contribution to the field. Choice A focuses on math, Choice C focuses on a mechanical invention rather than a foundational physics principle, and Choice B is too vague.",
    "chart": null,
