    "p": "In examining the impact of The Treaty of Tientsin on Chinese foreign relations, Sullivan and team observed that the treaty, while easing some tensions, also imposed conditions that were for China <span class=\"sat-blank\"></span>. These conditions included the opening of additional ports for trade and the legalization of the opium trade. which had long-term negative implications for China's sovereignty and economic stability.",
