    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "The following text is adapted from Charles Dickens's 'A Christmas Carol.' Ebenezer Scrooge is visited by the Ghost of Christmas Present. \"Spirit,\" said Scrooge submissively, \"conduct me where you will. I went forth last night on compulsion and I learnt a lesson which is working now. Tonight, if you have anything to teach me, let me profit by it.\" The Ghost then smiled and, with a wave of his great hand, all the hideous and appalling things had vanished. As Scrooge looked around, he found himself in a bustling and joyous Christmas market.",
    "q": "Which choice best states the main purpose of this passage from 'A Christmas Carol'?",
