    "category": "Central Ideas and Details",
    "p": "The following text is adapted from Murasaki Shikibu's 11th century novel The Tale of Genji. A courtier named Genji is reflecting on his romantic relationships. Genji, the Shining Prince. was not a man to find satisfaction in the love of just one woman. His heart was always on the move, seeking out new experiences and emotions. It was this passionate curiosity that had led him to such a wide range of women, from high-ranking court ladies to humble village maidens. His love was like a river, flowing freely, sometimes calm. and at other times, wild and turbulent.",
