    "qnum_in_module": 6,
    "domain": "Craft and Structure",
    "category": "Reading & Writing Comprehension",
    "p": "The following text is adapted from Truman Capote's 1958 novella 'Breakfast at Tiffany's.' Holly Golightly, a young woman in New York, is speaking with the narrator about her life and dreams. \"I've got the most terrifying news. I'm going to be absolutely broke for the next month. It's really put me in a terrible spot. I don't know what on earth I'm going to do,\" she fretted. \"l don't suppose you'd know anyone who'd like to buy a slightly used mink coat?\"",
