    "category": "Reading & Writing Comprehension",
    "p": "In Toni Morrison's 'Beloved', Sethe's house at 124 Bluestone Road is haunted by the ghost of her deceased daughter. The hauntings are disruptive, causing emotional distress to the inhabitants. However, when Paul D arrives and forces the spirit out, the house becomes quiet. Critics argue that the quieting of the house symbolizes Sethe's suppression of her traumatic past. Yet, when Beloved appears, the house becomes chaotic again. Some scholars suggest this indicates that confronting one's past. however painful, is necessary for healing.",
