    "p": "Many have labeled Albert Einstein the \"father of modern physics,\" a title that has been used in countless publications about him since his groundbreaking work in the early 20th century <span class=\"sat-blank\"></span>. Einstein himself rejected the father feeling that it didn't fully represent his commitment to the broader scientific community as well as \"scientific humanist,\" the label he favored.",
