    "domain": "Craft and Structure",
    "category": "Words in Context",
    "p": "The Treaty of Paris (1783), which marked the end of the American Revolutionary War, was a significant deviation from typical 18th-century treaties <span class=\"sat-blank\"></span>. Historically, treaties heavily favored the more powerful nations. However, this treaty, negotiated by Benjamin Franklin, John Adams, and John Jay, stood out for its nature. It was a stark contrast to previous agreements, particularly in its fair treatment of the United States regarding independence, territorial boundaries, and the rights of loyalists.",
