    "qnum_in_module": 4,
    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "The following text is adapted from Alice Walker's The Color Purple. Celie, the protagonist, is discussing her life. \"l never truly felt joy until I started writing letters to God. It was like a secret communication that only He and I could understand. It allowed me to pour out my feelings, all my pain and happiness, without fear of judgment or ridicule. It was my own form of catharsis, a way to cleanse my soul of all the bitterness that life had thrown at me. Writing these letters made me feel seen, made me feel heard, in a way that nothing else ever had.\"",
    "q": "Which choice best describes the main purpose of this passage?",
    "o": [
      "To illustrate Celie's deep religious conviction and her belief in the power of prayer",
      "To depict the protagonist's struggle in finding a suitable medium to express her feelings",
      "To highlight the therapeutic effect of writing and its ability to provide comfort",
      "To show the transformative impact of writing letters to God on Celie's emotional well-being"
    ],
    "a": 2,
    "e": "The text emphasizes how writing acts as a catharsis and cleanses her soul.",
    "chart": null,
