    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "St. Peter, according to Christian tradition, was one of the Twelve Apostles of Jesus Christ. He is often depicted holding the keys of heaven, symbolizing his role as the first Pope and his leadership in the early Church. Many stories highlight his faith and devotion, but also his human shortcomings, such as his denial of Christ before the crucifixion. Despite these weaknesses, his post-resurrection encounters with Christ reaffirmed his faith and duty, marking him as a central figure in Christian history.",
    "q": "Which choice best states the main purpose of the text?",
