    "variant": "Ninja Practice Test 2",
    "variant_num": 2,
    "module": "Module 2",
    "qnum_in_module": 9,
    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "In many rural communities, draft animals, such as horses and oxen, play a vital role in the local economy. These animals, known for their strength and endurance, are used for plowing fields, transporting goods, and even generating power in some instances. Their use is not only cost-effective but also environmentally friendly, as they produce less pollution than mechanized equipment. However, the maintenance of these animals requires significant resources, including food and veterinary care, which may impact the local economy.",
