    "domain": "Expression of Ideas",
    "category": "Rhetorical Synthesis",
    "p": "While researching a topic, a student has taken the following notes: • Historically, animals have played a vital role in aiding human procurement tasks. • A study led by Dr. Maria Gonzales focused on understanding the efficiency and effectiveness of animals in these roles. • Gonzales's team observed different animal species performing tasks like carrying loads, detecting substances, and guiding humans. • The researchers measured task completion times and success rates for each animal. • They found that animals significantly increased efficiency in procurement tasks, often outperforming mechanical alternatives.",
