    "variant": "Ninja Practice Test 3",
    "variant_num": 3,
    "module": "Module 1",
    "qnum_in_module": 3,
    "domain": "Craft and Structure",
    "category": "Words in Context",
    "p": "Neil Armstrong, an aeronautical engineer and astronaut, occupies a singular position in the annals of humanity's space exploration as the first person to set foot on the moon <span class=\"sat-blank\"></span>. His footprints on the lunar surface have made him an enduringly figure in global history. Armstrong's influence was clear throughout his extensive career in NASA, from his pioneering Gemini missions to his historic Apollo 11 lunar landing. Under his leadership, he pushed the boundaries of human potential, bringing about awe and inspiration. In addition to advancing space exploration, he played a crucial role in inspiring millions across the globe, kindling their curiosity and imagination.",
    "q": "Which choice completes the text with the most logical and precise word or phrase?",
    "o": [
      "persistent",
      "prolific",
      "profound",
      "iconic"
    ],
    "a": 3,
    "e": "The text describes Neil Armstrong as the first person to walk on the moon, emphasizing his profound and widely recognized influence ('enduringly figure in global history'). 'Iconic' precisely fits this description of a highly recognizable and revered historical figure. The other options don't logically describe a prominent historical figure in this context.",
    "chart": null,
    "num": 3,
    "p_img": "assets/questions/t3_m1_q3_p.webp",
