    "qnum_in_module": 6,
    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "The following text is adapted from Joseph Conrad's Heart of Darkness. Marlow is a seaman who has been sent to Africa by a Belgian trading company to retrieve the ill and possibly insane Mr. Kurtz. He was silent for a long time. 'l laid the ghost of his gifts at last with a lie,' he began suddenly. 'Girl! What? Did I mention a girl? Oh, she is out of it—completely. They—the women, I mean—are out of it—should be out of it. We must help them to stay in that beautiful world of their own, lest ours gets worse.'",
    "q": "Which choice best states the main purpose of the text?",
    "o": [
      "To express Marlow's contempt for the women who are not involved in his mission",
      "To highlight Marlow's belief that women should remain oblivious to the harsh realities of the world",
      "To detail Marlow's regret about lying and his desire for redemption",
      "To suggest that Marlow blames women for the worsening of his world"
    ],
    "a": 1,
    "e": "In the text, Marlow explicitly states, 'We must help them [women] to stay in that beautiful world of their own, lest ours gets worse.' This demonstrates his belief that women should be protected from and remain oblivious to the dark and harsh realities of the world he experiences.",
    "chart": null,
