    "e": "The claim is that the method used can greatly influence the perceived magnitude of Turing's contributions. Choice B supports this by showing that when the same method is used (citation analysis by Smith and Brown), the estimates are similar, but when different methods are used (by Johnson and Williams), the estimates differ substantially from the others.",
