    "domain": "Standard English Conventions",
    "category": "Boundaries & Grammar",
    "p": "The team faced significant challenges in the their determination never wavered <span class=\"sat-blank\"></span>. They had to work with limited resources and tight deadlines, which required innovative solutions and efficient time management. Each member brought unique skills to the table; their collaboration was a testament to their collective expertise and commitment. Despite the obstacles, they managed to complete the project ahead of schedule; this success not only boosted their confidence but also garnered praise from the company's leadership.",
