    "domain": "Craft and Structure",
    "category": "Words in Context",
    "p": "It is by no means to observe the influence of classic science fiction on modern space exploration technology; indeed, many contemporary space engineers cite works like Arthur C <span class=\"sat-blank\"></span>. Clarke's novels as inspirational. However, some experts argue that practical scientific advancements, rather than science fiction, have played a more crucial role in shaping current space technologies.",
