    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "The following text is adapted from Ernest Hemingway's 1929 novel 'A Farewell to Arms.' The protagonist, Lieutenant Frederic Henry, is an American serving as an ambulance driver on the Italian front during World War l. I was always embarrassed by the words sacred, glorious, and sacrifice and the expression in vain. We had heard them, sometimes standing in the rain almost out of earshot, so that only the shouted words came through, and had read them. on proclamations that were slapped up by billposters over other proclamations, only to be hated by the soldiers.",
