    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "The following text is adapted from Tennessee Williams's 1947 play 'A Streetcar Named Desire.' Blanche DuBois, a Southern belle with a tragic past, has come to New Orleans to live with her sister, Stella, and her husband, Stanley Kowalski. Blanche: I can't stand a naked light bulb, any more than I can a rude remark or a vulgar action. I tell you. I'm very adaptable. I can be just what you want me to be. Stanley: You've got this all mapped out, haven't you? But you're not going to make a monkey out of me.",
