    "category": "Rhetorical Synthesis",
    "p": "• • • • • While researching a topic, a student has taken the following notes: The orbits of planets in the solar system are influenced by gravitational interactions. Jupiter, being the largest planet, has a significant gravitational pull. The asteroid belt lies between Mars and Jupiter. The gravitational influence of Jupiter has been hypothesized to shape the structure of the asteroid belt. Some asteroids have been ejected from the belt due to Jupiter's gravitational disturbances.",
