    "p": "The following text is adapted from Harper Lee's 1960 novel To Kill a Mockingbird. Scout, the novel's young narrator, is speaking about her father, Atticus Finch. Atticus was feeble: he was nearly fifty. When Jem and I asked him why he was so old, he said he got started late, which we felt reflected upon his abilities and manliness. He was much older than the parents of our school contemporaries, and there was nothing Jem or I could say about him when our classmates said, \"My father—",
