    "p": "The following text is adapted from Truman Capote's 1958 novella 'Breakfast at Tiffany's.' Holly Golightly, the main character, is described by the narrator. She was never without dark glasses, she was always well groomed, there was a consequential good taste in the plainness of her clothes, the blues and greys and lack of lustre that made her, herself, shine so. One might have thought her a photographer's model, perhaps a young actress, except that it was obvious, looking at her, that she was not a society girl. She had a special manner.",
