    "domain": "Craft and Structure",
    "category": "Reading & Writing Comprehension",
    "p": "Text 1 Alfred Jarry is known for his avant-garde plays, particularly 'Ubu Roi', which broke away from conventional theatrical norms. His work was characterized by absurdism and a unique use of language, which he referred to as 'pataphysics'. This term is used to describe a philosophy that extends beyond metaphysics, dealing with the realm of imaginary solutions and the laws governing exceptions. Text 2 Literary critic Harold Bloom views Jarry's work as a precursor to the Theatre of the Absurd. He argues that Jarry's 'pataphysics', with its focus on the imaginary and the exceptional, laid the groundwork for later absurdist playwrights. Bloom suggests that Jarry's work pushed boundaries, challenging audiences with its defiance of logical norms and its embrace of the absurd.",
