    "domain": "Craft and Structure",
    "category": "Reading & Writing Comprehension",
    "p": "Karl Adolph Gjellerup was a Danish author who received the Nobel Prize for Literature in 1917 along with his compatriot Henrik Pontoppidan. Gjellerup's early work was influenced by the aesthetic and ethical ideas of such Danish philosophers as Soren Kierkegaard and Frederik Nietzsche, while his later work reflected his conversion to Buddhism, with its themes of renunciation and compassion. Despite his clear shift in philosophical allegiance, Gjellerup maintained a consistent focus on the human capacity for self-transcendence and the pursuit of higher moral and aesthetic ideals throughout his career.",
