    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "The following text is adapted from George Orwell's 1984. Winston, the protagonist, is having a conversation with O'Brien about the nature of the past. \"'Who controls the past controls the future: who controls the present controls the past,' repeated Winston obediently. 'And yet the past, though of its nature alterable, never has been altered. Whatever is true now was true from everlasting to everlasting. It is quite simple. All that is needed is an unending series of victories over your own memory. Reality control,' they called it: in Newspeak, 'doublethink.\"'",
    "q": "Which choice best states the primary purpose of this passage?",
    "o": [
      "To illustrate Winston's lack of understanding about the concept of 'doublethink.'",
      "To highlight the Party's manipulation of truth and reality through control of the past.",
      "To showcase a philosophical conversation between Winston and O'Brien about the nature of time.",
      "To describe the Newspeak language and its role in the society of Oceania."
    ],
    "a": 1,
    "e": "The passage explains how controlling the past allows control over the present and future.",
    "chart": null,
    "num": 4,
