    "p": "The following text is adapted from Mikhail Bulgakov's novel, The Master and Margarita. Woland, a mysterious foreigner, is speaking to Berlioz and Ivan about Jesus Christ. 'Never was there a more unfortunate and more cruel execution,' said the foreigner, and his voice trembled with indignation. 'But this execution was the most extraordinary thing. The real horror is that it absolutely had no cause, either legal or moral. He was sentenced for no reason at all.'",
