    "domain": "Information and Ideas",
    "category": "Central Ideas and Details",
    "p": "The following text is adapted from Wilkie Collins's 1859 novel 'The Woman in White.' Walter Hartright, a young art teacher, meets a mysterious woman dressed entirely in white who is in a state of distress. There was something so strange and striking about her aspect that even in the darkness I could see she was in a state of extraordinary excitement. Her face was deadly pale, with a spasm at her heart. As I declared that she was unharmed, she shrank back from me and from the view of the moon, and trembling from head to foot, she murmured in her turn, 'Thank God!'",
    "q": "Which choice best states the main purpose of the text?",
    "o": [
      "To emphasize the contrast between the woman's physical appearance n h r nn i n I",
      "To suggest the possibility of a romantic relationship between Walter and the woman in white.",
      "To convey the intense emotional state and the mysteriousness of the woman in white.",
      "To imply that the woman in white is a supernatural being due to her strange behavior."
    ],
    "a": 2,
