    "p": "Amedeo Modigliani, an Italian painter and sculptor, profoundly influenced modern portraiture. His innovative style, characterized by elongated necks and faces, departed from traditional portraiture, evoking an emotional depth not previously explored. Modigliani's work, though not widely recognized during his lifetime, has since garnered worldwide acclaim. His unique approach to portraiture has spurred artists to explore beyond conventional formats and techniques in their work, enriching the field of modern portraiture.",
