    "category": "Reading & Writing Comprehension",
    "p": "In an extensive study examining voter behavior in various European parliamentary elections, researchers Helena Schmidt and Marco DiCaprio sought to challenge the traditional notion that voting does not influence a voter's attitude towards political parties. They focused on first-time voters and non-voters of similar demographics across several elections. Schmidt and DiCaprio then compared the attitudes of these groups towards the major political parties in their respective countries one year after the elections.",
