    "p": "While researching a topic, a student has taken the following notes: • The Greek tragedy 'Prometheus Bound' features the Titan Prometheus, who defies the gods by stealing fire and giving it to humanity. • Zeus, the king of the gods, punishes Prometheus by having him bound to a rock where an eagle eats his liver daily. • In 'The Iliad', Zeus is depicted as the most powerful god, but also as temperamental and unpredictable. • In 'The Odyssey', Athena, the goddess of wisdom, assists the hero Odysseus throughout his journey. The god Apollo is often portrayed as the god of music, truth, and prophecy, and the sun.",
