    "p": "The following excerpt is adapted from William Shakespeare's 1599 play \"Julius Caesar.\" The speaker, Brutus, is contemplating the ramifications of joining a conspiracy against Caesar. 'Ilt must be by his death; and for my part, I know no personal cause to spurn at him, but for the general. He would be crowned: How that might change his nature, there's the question. It is the bright day that brings forth the adder; And that craves wary walking. Crown him?—that; And then, I grant, we put a sting in him, that at his will he may do danger with.\"",
