    "category": "Reading & Writing Comprehension",
    "p": "Text 1 Philosopher John Searle has proposed a theory of language known as 'speech act' theory. According to this theory, language is not just a system of communication but also a system of action. When we use language, we are performing actions, not just conveying information. Searle argues that understanding these actions is fundamental to understanding language itself. Text 2 Ludwig Wittgenstein, a philosopher of language, proposed a different view on the theory of language. He suggested that language is primarily a social activity, governed by rules and conventions. According to Wittgenstein, understanding these rules and how they are used in different social contexts is key to understanding language. He dismissed the idea that language is about performing actions, arguing that this perspective focuses too much on the individual speaker and not enough on the social context.",
