    "p": "The Bill of Rights, the first ten amendments to the United States Constitution, were ratified in 1791. They were designed to protect the basic rights of U.S. citizens, guaranteeing the freedom of speech, assembly, and worship. Historian Tom Schiller argues that the Bill of Rights was not just a protective shield but also a tool for societal change. He suggests that the broad interpretations of these amendments have led to significant societal changes, such as the Civil Rights Movement in the 1960s. His contention is that the Bill of Rights has been a catalyst for progress.",
