    "p": "During the Joseon Dynasty in Korea, scholar-officials were known for their calligraphic skills. They believed that the character of an individual was reflected in their calligraphy. Historian Kim Jang-yeol and his team studied calligraphy samples from this era and noted differences in script between scholar-officials who held high and low-ranking positions. Kim hypothesized that higher-ranking officials, with more rigorous training and responsibilities, exhibited a more refined and disciplined script than their lower- ranking counterparts.",
